#pragma once
#include "native_helpers.hpp"

constexpr uint64_t FRESH_SEED=202610126201ULL;
constexpr uint64_t PRIOR_SEED=202610128301ULL;
inline bool has_field(const J&j,const std::string&k){return j.object.count(k)!=0;}
inline bool value_present(const J&j,const std::string&k){return has_field(j,k)&&j.at(k).scalar!="null";}
inline std::vector<J> lines(const files::path&path){std::ifstream f(path);require(bool(f),"Cannot read JSONL");std::vector<J> result;std::string text;while(std::getline(f,text)){if(text.find_first_not_of(" \t\r")==std::string::npos)continue;Parser p;p.s=text;auto j=p.value();p.ws();require(p.i==p.s.size(),"Trailing JSONL bytes");result.push_back(std::move(j));}return result;}
struct Fixture {std::string id,split;P point;uint64_t d;std::string file_sha256;};

// Reproduce all eight previous fixtures before excluding their signed orbits.
// Only independent validation opens sidecars; a measured solver never does.
inline std::vector<Fixture> verify_prior_fixtures(const files::path&dir,Instance&instance){
 auto receipt=read_json((dir/"generator_receipt.json").string());auto sidecar=read_json((dir/"validation_sidecar.json").string());require(receipt.at("status").scalar=="PASS"&&num(receipt.at("seed"))==PRIOR_SEED,"Prior seed/status mismatch");check_modulus(receipt);require(num(receipt.at("subgroup_order"))==instance.r&&point(receipt.at("generator"))==instance.g,"Prior curve/G/r mismatch");require(digest(dir/"validation_sidecar.json")==receipt.at("validation_sidecar_sha256").scalar,"Prior sidecar hash mismatch");
 const auto&targets=receipt.at("targets").array;const auto&side=sidecar.at("entries").array;require(targets.size()==8&&side.size()==8,"Prior fixture count mismatch");std::vector<Fixture> result;SplitMix64 rng{PRIOR_SEED};uint64_t bound=instance.r-1,threshold=(uint64_t(0)-bound)%bound,range_rejects=0,orbit_rejects=0;std::string combined;
 for(size_t i=0;i<8;++i){const auto&t=targets[i];std::string split=i<3?"training":"holdout",id=split+"_"+std::to_string(i<3?i+1:i-2);require(t.at("fixture_id").scalar==id&&t.at("split").scalar==split&&side[i].at("fixture_id").scalar==id,"Prior split/order mismatch");P q=point(t.at("point"));require(!q.inf&&on(q)&&mul(instance.r,q).inf,"Prior point invalid");U key=orbit_key(q);require(!instance.excluded_orbits.count(key)&&dec(key)==t.at("signed_frobenius_orbit_key_decimal").scalar,"Prior orbit exclusion/key mismatch");uint64_t d=uint64_t(num(side[i].at("scalar_validation_only")));require(d>0&&d<instance.r&&point(side[i].at("point"))==q&&mul(d,instance.g)==q,"Prior scalar replay failure");
  while(true){auto raw=rng.next();if(raw<threshold){++range_rejects;continue;}auto proposal=raw%bound+1;auto candidate=mul(proposal,instance.g);if(instance.excluded_orbits.count(orbit_key(candidate))){++orbit_rejects;continue;}require(proposal==d&&candidate==q&&rng.draws==num(t.at("SplitMix64_draw_number")),"Prior SplitMix/rejection stream failure");break;}
  auto file=dir/t.at("point_file").scalar;auto hash=digest(file);require(hash==t.at("point_file_sha256").scalar,"Prior point hash mismatch");auto row=lines(file);require(row.size()==1&&point(row[0])==q,"Prior point-only file mismatch");if(i>=3)combined+=bytes(file);instance.excluded_orbits.insert(key);result.push_back({id,split,q,d,hash});
 }
 require(rng.draws==num(receipt.at("SplitMix64_draws"))&&range_rejects==num(receipt.at("uniform_range_rejections"))&&orbit_rejects==num(receipt.at("excluded_orbit_rejections")),"Prior stream counts mismatch");require(bytes(dir/"holdout_5_targets.jsonl")==combined&&digest(dir/"holdout_5_targets.jsonl")==receipt.at("holdout_combined_sha256").scalar,"Prior combined file mismatch");return result;
}

inline std::vector<Fixture> verify_fresh_fixtures(const files::path&dir,const files::path&prior_dir,const Instance&instance){
 auto receipt=read_json((dir/"generator_receipt.json").string()),sidecar=read_json((dir/"validation_sidecar.json").string());require(receipt.at("status").scalar=="PASS"&&num(receipt.at("seed"))==FRESH_SEED,"Fresh seed/status mismatch");check_modulus(receipt);require(num(receipt.at("subgroup_order"))==instance.r&&point(receipt.at("generator"))==instance.g,"Fresh curve/G/r mismatch");require(digest(dir/"validation_sidecar.json")==receipt.at("validation_sidecar_sha256").scalar,"Fresh sidecar hash mismatch");require(digest(prior_dir/"generator_receipt.json")==receipt.at("prior_optimization_generator_receipt_sha256").scalar,"Prior receipt binding mismatch");require(num(receipt.at("prior_optimization_targets_excluded"))==8&&num(receipt.at("initial_excluded_signed_orbits"))==instance.excluded_orbits.size(),"Fresh prior exclusion counts mismatch");
 const auto&targets=receipt.at("targets").array;const auto&side=sidecar.at("entries").array;require(targets.size()==8&&side.size()==8,"Fresh fixture count mismatch");std::vector<Fixture> out;auto excluded=instance.excluded_orbits;SplitMix64 rng{FRESH_SEED};uint64_t bound=instance.r-1,threshold=(uint64_t(0)-bound)%bound,range_rejects=0,orbit_rejects=0;std::string combined;require(num(receipt.at("scalar_bound_r_minus_one"))==bound&&num(receipt.at("uniform_rejection_threshold_2pow64_mod_bound"))==threshold,"Fresh sampling parameters mismatch");
 for(size_t i=0;i<8;++i){const auto&t=targets[i];std::string split=i<3?"training":"holdout",id=split+"_"+std::to_string(i<3?i+1:i-2);require(t.at("fixture_id").scalar==id&&t.at("split").scalar==split&&side[i].at("fixture_id").scalar==id,"Fresh split/order mismatch");P q=point(t.at("point"));require(on(q)&&!q.inf&&mul(instance.r,q).inf,"Fresh curve/subgroup failure");U key=orbit_key(q);require(!excluded.count(key)&&dec(key)==t.at("signed_frobenius_orbit_key_decimal").scalar,"Fresh point overlaps prior/base/accepted orbit or key mismatch");uint64_t d=uint64_t(num(side[i].at("scalar_validation_only")));require(d>0&&d<instance.r&&point(side[i].at("point"))==q&&mul(d,instance.g)==q,"Fresh sidecar scalar replay failure");
  while(true){auto raw=rng.next();if(raw<threshold){++range_rejects;continue;}auto proposal=raw%bound+1;auto candidate=mul(proposal,instance.g);if(excluded.count(orbit_key(candidate))){++orbit_rejects;continue;}require(proposal==d&&candidate==q&&rng.draws==num(t.at("SplitMix64_draw_number")),"Fresh exact SplitMix/rejection stream failure");break;}excluded.insert(key);auto file=dir/t.at("point_file").scalar;auto hash=digest(file);require(hash==t.at("point_file_sha256").scalar,"Fresh point digest mismatch");auto row=lines(file);require(row.size()==1&&point(row[0])==q,"Fresh individual file mismatch");if(i>=3)combined+=bytes(file);out.push_back({id,split,q,d,hash});
 }
 require(rng.draws==num(receipt.at("SplitMix64_draws"))&&range_rejects==num(receipt.at("uniform_range_rejections"))&&orbit_rejects==num(receipt.at("excluded_orbit_rejections")),"Fresh stream count mismatch");require(bytes(dir/"holdout_5_targets.jsonl")==combined&&digest(dir/"holdout_5_targets.jsonl")==receipt.at("holdout_combined_sha256").scalar,"Fresh combined file mismatch");return out;
}
